import{_ as p,a0 as o,w as s,s as d,ao as r,I as n,x as e,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Inkscape - 開源適量圖形編輯器 | LCTT x X-CMD","titleTemplate":false,"description":"Inkscape - 開源適量圖形編輯器 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Inkscape - 開源適量圖形編輯器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Inkscape - 開源適量圖形編輯器 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150409 Install Inkscape - Open Source Vector Graphic Editor","title":"Inkscape - 開源適量圖形編輯器","tag":"201505","desc":""},"relativePath":"201505/20150409 Install Inkscape - Open Source Vector Graphic Editor.md","filePath":"[post].md"}'),u={name:"201505/20150409 Install Inkscape - Open Source Vector Graphic Editor.md"};function k(h,a,c,m,I,P){const l=o("Link");return s(),d("div",null,[a[19]||(a[19]=r('<h1 id="inkscape-開源適量圖形編輯器" tabindex="-1">Inkscape - 開源適量圖形編輯器 <a class="header-anchor" href="#inkscape-開源適量圖形編輯器" aria-label="Permalink to “Inkscape - 開源適量圖形編輯器”">​</a></h1><p>Inkscape是一款開源矢量圖形編輯工具，並不同於Xara X、Corel Draw和Adobe Illustrator等競爭對手，它使用的是可縮放矢量圖形(SVG)圖形格式。SVG是一個廣泛部署、免版税使用的圖形格式，由W3C SVG工作組開發和維護。這是一個跨平台工具，完美運行於Linux、Windows和Mac OS上。</p><p>Inkscape始於2003年，起初它的bug跟蹤系統託管於Sourceforge上，但是後來遷移到了Launchpad上。當前它最新的一個穩定版本是0.91，它不斷地在發展和修改中。我們將在本文裏瞭解一下它的突出特點和安裝過程。</p><h3 id="顯著特性" tabindex="-1">顯著特性 <a class="header-anchor" href="#顯著特性" aria-label="Permalink to “顯著特性”">​</a></h3><p>讓我們直接來了解這款應用程序的顯著特性。</p><h4 id="創建對象" tabindex="-1">創建對象 <a class="header-anchor" href="#創建對象" aria-label="Permalink to “創建對象”">​</a></h4><ul><li>用鉛筆工具來畫出不同顏色、大小和形狀的手繪線，用貝塞爾曲線（筆式）工具來畫出直線和曲線，通過書法工具來應用到手寫的書法筆畫上等等</li><li>用文本工具來創建、選擇、編輯和格式化文本。在純文本框、在路徑上或在形狀裏操作文本</li><li>方便繪製各種形狀，像矩形、橢圓形、圓形、弧線、多邊形、星形和螺旋形等等並調整其大小、旋轉並修改（圓角化）它們</li><li>用簡單地命令創建並嵌入位圖</li></ul><h4 id="對象處理" tabindex="-1">對象處理 <a class="header-anchor" href="#對象處理" aria-label="Permalink to “對象處理”">​</a></h4><ul><li>通過交互式操作和調整參量來扭曲、移動、測量、旋轉目標</li><li>可以對 Z 軸進行提升或降低操作。</li><li>通過對象組合和取消組合可以創建一個虛擬層用來編輯或處理</li><li>圖層採用層次結構樹的結構，並且能鎖定或以各式各樣的處理方式來重新佈置</li><li>分佈與對齊指令</li></ul><h4 id="填充與邊框" tabindex="-1">填充與邊框 <a class="header-anchor" href="#填充與邊框" aria-label="Permalink to “填充與邊框”">​</a></h4><ul><li>可以複製/粘貼不同風格</li><li>取色工具</li><li>用RGB, HSL, CMS, CMYK和色盤這四種不同的方式選色</li><li>漸變層編輯器能創建和管理多停點漸變層</li><li>使用圖像或其它選擇區作為花紋填充</li><li>用一些預定義點狀花紋進行筆觸填充</li><li>通過路徑標示器標示開始、對摺和結束點</li></ul><h4 id="路徑上的操作" tabindex="-1">路徑上的操作 <a class="header-anchor" href="#路徑上的操作" aria-label="Permalink to “路徑上的操作”">​</a></h4><ul><li>節點編輯：移動節點和貝塞爾曲線控制點，節點的對齊和分佈等等</li><li>布爾運算（是或否）</li><li>運用可變的路徑起迄點可簡化路徑</li><li>路徑插入和增設連同動態和鏈接偏移對象</li><li>通過路徑追蹤把位圖圖像轉換成路徑(彩色或單色路徑）</li></ul><h4 id="文本處理" tabindex="-1">文本處理 <a class="header-anchor" href="#文本處理" aria-label="Permalink to “文本處理”">​</a></h4><ul><li>所有安裝好的框線字體都能用，甚至可以從右至左對齊對象</li><li>格式化文本、調整字母間距、行間距或列間距</li><li>路徑上和形狀上的文本中的文本、路徑或形狀都可以被編輯和修改</li></ul><h4 id="渲染" tabindex="-1">渲染 <a class="header-anchor" href="#渲染" aria-label="Permalink to “渲染”">​</a></h4><ul><li>Inkscape完全支持抗鋸齒顯示，這是一種通過柔化邊界上的像素從而減少或消除凹凸鋸齒的技術。</li><li>支持alpha透明顯示和PNG格式圖片的導出</li></ul><h3 id="在ubuntu-14-04和14-10上安裝inkscape" tabindex="-1">在Ubuntu 14.04和14.10上安裝Inkscape <a class="header-anchor" href="#在ubuntu-14-04和14-10上安裝inkscape" aria-label="Permalink to “在Ubuntu 14.04和14.10上安裝Inkscape”">​</a></h3>',18)),n("p",null,[a[1]||(a[1]=e("為了在Ubuntu上安裝Inkscape，我們首先需要 ",-1)),t(l,{href:"https://launchpad.net/~inkscape.dev/+archive/ubuntu/stable"},{default:i(()=>[...a[0]||(a[0]=[e("添加它的穩定版Personal Package Archive",-1)])]),_:1}),a[2]||(a[2]=e(" (PPA) 至Advanced Package Tool (APT) 庫中。打開終端並運行一下命令來添加它的PPA：",-1))]),a[20]||(a[20]=r(`<pre><code> sudo add-apt-repository ppa:inkscape.dev/stable
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/PPA-Inkscape.png" alt="PPA Inkscape"></p><p>PPA添加到APT庫中後，我們要用以下命令進行更新：</p><pre><code> sudo apt-get update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Update-APT2.png" alt="Update APT"></p><p>更新好庫之後，我們準備用以下命令來完成安裝：</p><pre><code> sudo apt-get install inkscape
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Install-Inkscape.png" alt="Install Inkscape"></p><p>恭喜，現在Inkscape已經被安裝好了，我們可以充分利用它的豐富功能特點來編輯製作圖像了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Inkscape-Main1.png" alt="Inkscape Main"></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3>`,11)),n("p",null,[a[4]||(a[4]=e("Inkscape是一款特點鮮明的圖形編輯工具，它給予用户充分發揮自己藝術能力的權利。它還是一款自由安裝和自定義的開源應用，並且支持各種文件類型，包括JPEG, PNG, GIF和PDF及更多。訪問它的 ",-1)),t(l,{href:"https://inkscape.org/en/"},{default:i(()=>[...a[3]||(a[3]=[e("官方網站",-1)])]),_:1}),a[5]||(a[5]=e(" 來獲取更多新聞和應用更新。",-1))]),a[21]||(a[21]=n("hr",null,null,-1)),n("p",null,[a[7]||(a[7]=e("via: ",-1)),t(l,{href:"http://linoxide.com/tools/install-inkscape-open-source-vector-graphic-editor/"},{default:i(()=>[...a[6]||(a[6]=[e("http://linoxide.com/tools/install-inkscape-open-source-vector-graphic-editor/",-1)])]),_:1})]),n("p",null,[a[11]||(a[11]=e("作者：",-1)),t(l,{href:"http://linoxide.com/author/arunrz/"},{default:i(()=>[...a[8]||(a[8]=[e("Aun Raza",-1)])]),_:1}),a[12]||(a[12]=e(" 譯者：",-1)),t(l,{href:"https://github.com/ZTinoZ"},{default:i(()=>[...a[9]||(a[9]=[e("ZTinoZ",-1)])]),_:1}),a[13]||(a[13]=e(" 校對：",-1)),t(l,{href:"https://github.com/wxy"},{default:i(()=>[...a[10]||(a[10]=[e("wxy",-1)])]),_:1})]),n("p",null,[a[16]||(a[16]=e("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[14]||(a[14]=[e("LCTT",-1)])]),_:1}),a[17]||(a[17]=e(" 原創翻譯，",-1)),t(l,{href:"http://linux.cn/"},{default:i(()=>[...a[15]||(a[15]=[e("Linux中國",-1)])]),_:1}),a[18]||(a[18]=e(" 榮譽推出",-1))])])}const x=p(u,[["render",k]]);export{T as __pageData,x as default};
